css:
.wo-header h2 {
  font-size: 16px;
  margin: 0 0 10px;
  color: #241c22;
}
.wo-meta {
  font-size: 10.5px;
  color: #423d52;
  display: flex;
  flex-wrap: wrap;
  gap: 4px 20px;
  margin-bottom: 4px;
}
.wo-meta-label {
  color: #6b6478;
}
.wo-rule {
  border: none;
  border-top: 1px solid #e4ddef;
  margin: 10px 0 16px;
}
.wo-content {
  font-size: 12px;
  line-height: 1.6;
}
